def merge_intervals(intervals):
    if not intervals:
        return []

    sorted_intervals = sorted([[s, e] for s, e in intervals], key=lambda x: (x[0], x[1]))

    merged = [list(sorted_intervals[0])]

    for current in sorted_intervals[1:]:
        if current[0] <= merged[-1][1]:
            merged[-1][1] = max(merged[-1][1], current[1])
        else:
            merged.append(list(current))

    return merged

import heapq


def toposort(nodes, edges):
    unique_edges = set(edges)

    adj = {node: set() for node in nodes}
    in_degree = {node: 0 for node in nodes}

    for src, dst in unique_edges:
        adj[src].add(dst)
        in_degree[dst] += 1

    heap = [node for node in nodes if in_degree[node] == 0]
    heapq.heapify(heap)

    result = []
    while heap:
        node = heapq.heappop(heap)
        result.append(node)
        for neighbor in adj[node]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                heapq.heappush(heap, neighbor)

    if len(result) != len(nodes):
        raise ValueError("Cycle detected")

    return result

def stable_batches(items, limit):
    if limit <= 0:
        raise ValueError
    if not items:
        return []
    for _, w in items:
        if w <= 0 or w > limit:
            raise ValueError
    batches = []
    current = []
    total = 0
    for name, w in items:
        if current and total + w > limit:
            batches.append(current)
            current = []
            total = 0
        current.append(name)
        total += w
    if current:
        batches.append(current)
    return batches

import re


def parse_env(text):
    result = {}
    key_re = re.compile(r'^[A-Za-z_][A-Za-z0-9_]*$')

    for line in text.splitlines():
        line = line.strip()

        if not line or line.startswith('#'):
            continue

        if '=' not in line:
            raise ValueError(f"Invalid line (no '='): {line!r}")

        key, value = line.split('=', 1)
        key = key.strip()
        value = value.strip()

        if not key_re.match(key):
            raise ValueError(f"Invalid key: {key!r}")

        if len(value) >= 2:
            if (value[0] == '"' and value[-1] == '"') or (value[0] == "'" and value[-1] == "'"):
                value = value[1:-1]

        result[key] = value

    return result

def parse_sse(chunks):
    raw = b''.join(chunks)
    text = raw.decode('utf-8')

    lines = text.split('\n')
    lines = [line[:-1] if line.endswith('\r') else line for line in lines]

    if text.endswith('\n'):
        lines = lines[:-1]

    events = []
    current_data = []

    for line in lines:
        if line == '':
            if current_data:
                data = '\n'.join(current_data)
                if data == '[DONE]':
                    break
                events.append(data)
            current_data = []
        elif line.startswith(':'):
            continue
        elif ':' in line:
            field, value = line.split(':', 1)
            if field == 'data':
                if value.startswith(' '):
                    value = value[1:]
                current_data.append(value)

    return events

import math


def retry_delay(attempt, base, cap):
    """Return float(min(cap, base * 2**attempt)) safely."""
    if attempt < 0 or base < 0 or cap < 0:
        raise ValueError("arguments must be nonnegative")

    if base == 0 or cap == 0:
        return 0.0

    # At this point base > 0 and cap > 0.
    # If base already >= cap, the product is certainly >= cap for any attempt >= 0.
    if base >= cap:
        return float(cap)

    # base < cap, so cap / base > 1.
    # Check whether base * 2**attempt >= cap  <=>  attempt >= log2(cap / base).
    # This avoids ever computing 2**attempt for huge attempt values.
    threshold = math.log2(cap / base)
    if attempt >= threshold:
        return float(cap)

    # Here attempt < log2(cap / base), which bounds attempt to a small integer
    # (at most ~1096 for finite floats), so ldexp is safe and exact.
    return float(math.ldexp(base, attempt))

def fifo_admit(active, queued, budget, slots):
    for r in queued:
        if r > budget:
            raise ValueError(f"queued reservation {r} exceeds budget {budget}")

    remaining_budget = budget - sum(active)
    remaining_slots = slots - len(active)

    admitted = []
    remaining = []

    for i, r in enumerate(queued):
        if remaining_slots > 0 and r <= remaining_budget:
            admitted.append(r)
            remaining_budget -= r
            remaining_slots -= 1
        else:
            remaining = list(queued[i:])
            break
    else:
        remaining = []

    return (admitted, remaining)
